-- A vote, report or appeal is about exactly one thread or one post.
ALTER TABLE "community_votes" ADD CONSTRAINT "community_votes_one_target"
  CHECK (("threadId" IS NULL) <> ("postId" IS NULL));
ALTER TABLE "community_reports" ADD CONSTRAINT "community_reports_one_target"
  CHECK (("threadId" IS NULL) <> ("postId" IS NULL));
ALTER TABLE "community_appeals" ADD CONSTRAINT "community_appeals_one_target"
  CHECK (("threadId" IS NULL) <> ("postId" IS NULL));
ALTER TABLE "community_threads" ADD CONSTRAINT "community_threads_counts_nonnegative"
  CHECK ("voteCount" >= 0 AND "replyCount" >= 0);
ALTER TABLE "community_posts" ADD CONSTRAINT "community_posts_votes_nonnegative"
  CHECK ("voteCount" >= 0);

-- The application connects as the owner, so it is unaffected. With no policy,
